python3 -c 'import os,time,json,math;P=os.getenv("TM_STATE","rhgc.state");g=int(open(P).read())if os.path.exists(P)else 0;W=os.getenv("TM_WORD","1");T=os.getenv("TM_TARGET","0");K=int(os.getenv("TM_GC","15"));S=float(os.getenv("TM_SLEEP",".2"));A="ATGC";J=lambda x:json.dumps(x,separators=(",",":"));exec("while 1:\n ok=[];bad=0\n for p in range(g+1):\n  w=(math.isqrt(8*p+1)-1)//2;t=w*(w+1)//2;b=p-t;k=w-b+1;c=b;B=4*(k+1);q=h=0;M={i for i,x in enumerate(W)if x==\"1\"};z=0;n=g-p+1\n  for z in range(1,n+1):\n   a=int(h in M);j=2*q+a;d=(c//pow(B,j))%B;r=d%(k+1);d//=k+1;m=d%2;d//=2;v=d%2;(M.add(h)if v else M.discard(h));h+=1 if m else-1;q=r\n   if q==k:break\n  if q==k and z==n and \"\".join(\"1\"if i in M else\"0\"for i in range(len(T)))==T:\n   s=f\"{p}:{k}:{c}:{z}\";x=\"\".join(A[(v>>j)&3]for v in s.encode()for j in(6,4,2,0));gc=sum(v in\"GC\"for v in x);u=1\n   for v in x:u=u*4+A.index(v)\n   if gc==K:ok.append({\"p\":p,\"tm\":[k,c,z],\"atgc\":x,\"uid\":u,\"gc\":gc,\"sigma\":[gc,2*K],\"coherent\":1})\n   else:bad+=1\n open(P,\"w\").write(str(g+1));print(J({\"protocol\":\"HU-AUTO-UTM-RH-ATGC-Safe/1.0\",\"generation\":g,\"critical_gc\":K,\"accepted\":ok,\"rejected_noncritical\":bad,\"invariant\":\"gc=K <=> log(B^gc)/log(B^(2K))=1/2\",\"claims\":{\"rh_proved\":0,\"zeta_zero_test\":0,\"host_shell_exec\":0,\"global_halting_decider\":0,\"self_awareness\":0}}),flush=True);g+=1;time.sleep(S)")' 